import React, { createContext, useContext, useEffect, useState } from 'react';
import { load, save } from '../utils/storage';
import { validateAndUseKey, createAccessKey, loadKeys } from '../utils/data';

const AuthContext = createContext(null);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [users, setUsers] = useState(() => load('users', []));
  const [currentUser, setCurrentUser] = useState(() => load('currentUser', null));

  useEffect(() => save('users', users), [users]);
  useEffect(() => save('currentUser', currentUser), [currentUser]);

  const register = ({ username, password, displayName, bio, accessKey }) => {
    // Must provide and validate access key
    const res = validateAndUseKey(accessKey);
    if (!res.valid) throw new Error(res.reason || 'Key inválida');
    if (users.find(u => u.username === username)) {
      throw new Error('Usuario ya existe');
    }
    const newUser = { id: Date.now(), username, password, displayName: displayName || username, bio: bio || '', avatarColor: '#'+Math.floor(Math.random()*16777215).toString(16), keyRole: res.role, keyExpiresAt: res.expiresAt };
    setUsers(prev => [newUser, ...prev]);
    setCurrentUser(newUser);
    return newUser;
  };

  const login = ({ username, password, accessKey }) => {
    // If accessKey provided, validate it
    if (accessKey) {
      const res = validateAndUseKey(accessKey);
      if (!res.valid) throw new Error(res.reason || 'Key inválida');
    }
    const user = users.find(u => u.username === username && u.password === password);
    if (!user) throw new Error('Credenciales inválidas');
    setCurrentUser(user);
    return user;
  };

  const createKey = ({ daysValid = 7, singleUse = true, role = 'user' } = {}) => {
    return createAccessKey({ daysValid, singleUse, role });
  };

  const logout = () => setCurrentUser(null);

  const updateProfile = (updates) => {
    setUsers(prev => prev.map(u => u.id === currentUser.id ? { ...u, ...updates } : u));
    setCurrentUser(prev => ({ ...prev, ...updates }));
  };

  return (
    <AuthContext.Provider value={{ users, currentUser, register, login, logout, updateProfile, createKey, loadKeys }}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthContext;
